A.routes=i=>{if(A.navigation)return A.navigation[i];const [x,y,w,h]=A.panels[i];return A.routePixels[i].map(r=>r.map(([px,py])=>({x:(px-x)*1000/w,y:(py-y)*600/h})));};
A.load=async()=>{A.navigation=await fetch('assets/navigation.json').then(r=>{if(!r.ok)throw new Error('Navigation failed to load');return r.json();});const get=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('Artwork could not load: '+src));im.src=src;});[A.worlds,A.towers,A.enemies,A.menu,A.walk,A.extraTowers,A.groundAtlas,A.vehicleAtlas,A.airAtlas]=await Promise.all(['approved-worlds.png','towers.png','enemies.png','planets.png','alien-walk.png','extra-towers.png','ground-roster.png','vehicle-roster.png','air-roster.png'].map(p=>get('assets/'+p)));for(let i=0;i<10;i++){const cv=document.createElement('canvas');cv.width=1000;cv.height=600;const ctx=cv.getContext('2d');ctx.drawImage(A.worlds,...A.panels[i],0,0,1000,600);A.masks[i]=ctx.getImageData(0,0,1000,600).data;}
for(let i=0;i<10;i++){const cv=document.createElement('canvas');cv.width=180;cv.height=180;const ctx=cv.getContext('2d'),w=A.menu.width/5,h=A.menu.height/2;ctx.drawImage(A.menu,(i%5)*w,Math.floor(i/5)*h,w,h,0,0,180,180);A.planetImages.push(cv.toDataURL());}A.frames=[];A.walkFrames=[];
// Crop safe cell interiors, then anchor each frame by its opaque body and feet.
const frame=(im,x,y,w,h,clean=false)=>{const cv=document.createElement('canvas');cv.width=Math.floor(w);cv.height=Math.floor(h);const ctx=cv.getContext('2d');ctx.drawImage(im,x,y,w,h,0,0,cv.width,cv.height);const px=ctx.getImageData(0,0,cv.width,cv.height);if(clean){cleanSpriteAlpha(px);ctx.putImageData(px,0,0);}let left=cv.width,top=cv.height,right=0,bottom=0;for(let yy=0;yy<cv.height;yy++)for(let xx=0;xx<cv.width;xx++){const k=(yy*cv.width+xx)*4;if(px.data[k+3]>190){left=Math.min(left,xx);right=Math.max(right,xx);top=Math.min(top,yy);bottom=Math.max(bottom,yy);}}return{image:cv,x:Math.max(0,left-2),y:Math.max(0,top-2),w:Math.max(1,right-left+5),h:Math.max(1,bottom-top+5)};};
for(let row=0;row<2;row++)for(let col=0;col<5;col++){const w=A.enemies.width/5,h=A.enemies.height/2;A.frames.push(frame(A.enemies,col*w+w*.045,row*h+h*.045,w*.91,h*.91,true));}
for(let i=0;i<8;i++){const w=A.walk.width/4,h=A.walk.height/2;A.walkFrames.push(frame(A.walk,(i%4)*w+w*.04,Math.floor(i/4)*h+h*.035,w*.92,h*.93,true));}A.extraFrames=[];for(let row=0;row<3;row++){const [top,bottom]=[[0,370],[374,755],[758,1195]][row];for(let col=0;col<4;col++){const w=A.extraTowers.width/4;A.extraFrames.push(frame(A.extraTowers,col*w+w*.025,top,w*.95,bottom-top));}}A.rosterFrames={};for(const [group,sheet]of[['ground',A.groundAtlas],['vehicle',A.vehicleAtlas],['air',A.airAtlas]]){A.rosterFrames[group]=[];const edges={ground:[0,.122,.232,.346,.535,.684,.830,1],vehicle:[0,.137,.243,.386,.527,.655,.811,1],air:[0,.149,.295,.426,.56,.675,.84,1]}[group];for(let i=0;i<7;i++){const x=edges[i]*sheet.width,w=(edges[i+1]-edges[i])*sheet.width;A.rosterFrames[group].push(frame(sheet,x+1,sheet.height*.025,w-2,sheet.height*.95,true));}}A.ready=true;};
A.buildable=(i,p)=>{const pixels=A.masks[i];if(!pixels)return true;for(const [dx,dy]of[[0,0],[-15,0],[15,0],[0,12],[0,-12]]){const x=Math.round(p.x+dx),y=Math.round(p.y+dy);if(x<0||x>=1000||y<0||y>=600)return false;const k=(y*1000+x)*4,r=pixels[k],gg=pixels[k+1],b=pixels[k+2];if(i===0||i===2||i===4){if(!(gg>r*.94&&gg>b*1.05&&gg>45))return false;}else if(i===5){if(!(b>r*1.15&&gg>r*1.2&&b>45))return false;}else if(i===1||i===7){if(!(r>gg*1.14&&gg>b*1.05&&r>90))return false;}else if(i===3||i===9){if(Math.max(r,gg,b)-Math.min(r,gg,b)>75||Math.max(r,gg,b)>190)return false;}else if(i===6){if(gg<45||gg<r*.8||gg<b*.82)return false;}else if(i===8){if(Math.max(r,gg,b)-Math.min(r,gg,b)>55||Math.max(r,gg,b)>165)return false;}}
return true;};
A.tower=(c,t,alpha=1)=>{if(t.type>=6){const f=A.extraFrames?.[(t.level-1)*4+t.type-6];if(!f)return;const h=72+(t.level-1)*8,w=f.w*h/f.h;c.save();c.globalAlpha*=alpha;c.translate(t.x,t.y);if(Math.cos(t.angle)<0)c.scale(-1,1);c.drawImage(f.image,f.x,f.y,f.w,f.h,-w/2,8-h,w,h);c.restore();return;}const sheet=t.type<6?A.towers:A.extraTowers,columns=t.type<6?6:4,column=t.type<6?t.type:t.type-6,w=sheet.width/columns,h=sheet.height/3,size=78+(t.level-1)*7;c.save();c.globalAlpha*=alpha;c.translate(t.x,t.y);if(Math.cos(t.angle)<0)c.scale(-1,1);c.drawImage(sheet,column*w,(t.level-1)*h,w,h,-size*.5,-size*.86,size,size);c.restore();};
A.frameFor=kind=>{if(kind==='grunt')return A.walkFrames[0];const def=A.roster?.[kind];if(def&&A.rosterFrames?.[def.group])return A.rosterFrames[def.group][def.sprite];const col={grunt:0,runner:1,armour:2,air:3,boss:4}[kind];return A.frames[col];};
A.enemy=(c,e,time)=>{const def=A.roster?.[e.kind],air=e.flying??def?.group==='air',step=e.d/(e.kind==='runner'?8:11);let f=e.kind==='grunt'?A.walkFrames[Math.floor(e.d/7)%8]:A.frameFor(e.kind);if(!f)return;const height=e.size||def?.size||(air?42:39),width=f.w*height/f.h,bounce=air?0:Math.sin(step*Math.PI)*(def?.group==='vehicle'?.2:.5);c.save();c.translate(e.x,e.y);c.fillStyle='#08172045';c.beginPath();c.ellipse(0,1,Math.min(30,height*.25),air?5:3.5,0,0,Math.PI*2);c.fill();c.translate(0,bounce-(air?12:0));if(Math.cos(e.angle)<0)c.scale(-1,1);c.drawImage(f.image,f.x,f.y,f.w,f.h,-width/2,-height,width,height);c.restore();};
// Keep each sprite's connected body, with a soft two-pixel edge, and discard atlas-neighbour fragments.
function cleanSpriteAlpha(px){const {width:w,height:h,data}=px,n=w*h,labels=new Int32Array(n),queue=new Int32Array(n),sizes=[0];let id=0,largest=0;for(let start=0;start<n;start++){if(labels[start]||data[start*4+3]<200)continue;id++;let head=0,tail=1;queue[0]=start;labels[start]=id;while(head<tail){const p=queue[head++],x=p%w,y=Math.floor(p/w);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=x+dx,yy=y+dy;if(xx<0||xx>=w||yy<0||yy>=h)continue;const q=yy*w+xx;if(!labels[q]&&data[q*4+3]>=200){labels[q]=id;queue[tail++]=q;}}}sizes[id]=tail;largest=Math.max(largest,tail);}if(!largest)return;const keep=new Uint8Array(n);for(let p=0;p<n;p++)if(labels[p]&&sizes[labels[p]]>=largest*.06){const x=p%w,y=Math.floor(p/w);for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const xx=x+dx,yy=y+dy;if(xx>=0&&xx<w&&yy>=0&&yy<h)keep[yy*w+xx]=1;}}for(let p=0;p<n;p++)if(!keep[p]||data[p*4+3]<55)data[p*4+3]=0;}
